CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "login_id" varchar(50) UNIQUE NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "email_verified" boolean NOT NULL DEFAULT false,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "free_posts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "content" text NOT NULL,
  "view_count" int NOT NULL DEFAULT 0,
  "like_count" int NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "question_posts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "content" text NOT NULL,
  "question_category" varchar(50),
  "question_status" varchar(20) NOT NULL DEFAULT 'OPEN',
  "view_count" int NOT NULL DEFAULT 0,
  "checked_commentid" int,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "resolved_at" timestamptz
);

CREATE TABLE "dispute_posts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "content" text NOT NULL,
  "merchant_name" varchar(255),
  "purchase_site" varchar(255),
  "dispute_type" varchar(50),
  "resolution_status" varchar(30) NOT NULL DEFAULT 'IN_PROGRESS',
  "view_count" int NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "community_comments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "free_post_id" bigint,
  "question_post_id" bigint,
  "dispute_post_id" bigint,
  "content" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "cases" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "case_type" varchar(50) NOT NULL,
  "status" varchar(30) NOT NULL DEFAULT 'REGISTERED',
  "merchant_name" varchar(255) NOT NULL,
  "purchase_site" varchar(500) NOT NULL,
  "order_number" varchar(100),
  "purchase_date" date,
  "payment_amount" decimal(15,2), -- 원화(KRW) 기준 결제 금액
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "resolved_at" timestamptz
);

CREATE TABLE "case_evidences" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "evidence_type" varchar(50) NOT NULL,
  "description" text,
  "original_filename" varchar(255) NOT NULL,
  "stored_filename" varchar(255) NOT NULL,
  "file_path" varchar(1000) NOT NULL,
  "file_size" bigint NOT NULL,
  "content_type" varchar(100),
  "analysis_status" varchar(20) NOT NULL DEFAULT 'PENDING',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "case_status_histories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "status" varchar(30),
  "description" text,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "email_drafts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "purpose" varchar(100) NOT NULL,
  "recipient_email" varchar(255),
  "subject" varchar(255) NOT NULL,
  "body" text NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'DRAFT',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "gmail_connections" (
  "id" BIGSERIAL PRIMARY KEY,
  "user_id" bigint UNIQUE NOT NULL,
  "google_email" varchar(320) NOT NULL,
  "refresh_token_encrypted" text,
  "scopes" text NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'CONNECTED',
  "connected_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

COMMENT ON TABLE "gmail_connections" IS 'Gmail 연동 및 암호화된 리프레시 토큰 관리. 회원당 하나의 Gmail 계정을 연결한다.';

CREATE TABLE "email_draft_attachments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email_draft_id" bigint NOT NULL,
  "evidence_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "case_email_threads" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "gmail_connection_id" bigint NOT NULL,
  "gmail_thread_id" varchar(255) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "email_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_email_thread_id" bigint NOT NULL,
  "gmail_message_id" varchar(255) NOT NULL,
  "sender_email" varchar(320) NOT NULL,
  "recipient_email" text,
  "subject" varchar(500),
  "body" text,
  "direction" varchar(10) NOT NULL,
  "received_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "orchestrator_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "trigger_type" varchar(30) NOT NULL,
  "trigger_key" varchar(255) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'PENDING',
  "next_action" varchar(50),
  "result_data" jsonb,
  "error_message" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "completed_at" timestamptz
);

CREATE UNIQUE INDEX ON "case_email_threads" ("gmail_connection_id", "gmail_thread_id");

CREATE INDEX ON "case_email_threads" ("case_id");

CREATE UNIQUE INDEX ON "email_messages" ("case_email_thread_id", "gmail_message_id");

CREATE INDEX ON "email_messages" ("case_email_thread_id", "received_at");

CREATE INDEX ON "orchestrator_runs" ("case_id", "created_at");

CREATE UNIQUE INDEX ON "orchestrator_runs" ("case_id", "trigger_type", "trigger_key");

CREATE INDEX ON "free_posts" ("user_id");

CREATE INDEX ON "free_posts" ("created_at");

CREATE INDEX ON "question_posts" ("user_id");

CREATE INDEX ON "question_posts" ("question_status", "created_at");

CREATE INDEX ON "dispute_posts" ("user_id");

CREATE INDEX ON "dispute_posts" ("dispute_type", "resolution_status");

CREATE INDEX ON "community_comments" ("free_post_id", "created_at");

CREATE INDEX ON "community_comments" ("question_post_id", "created_at");

CREATE INDEX ON "community_comments" ("dispute_post_id", "created_at");

CREATE INDEX ON "community_comments" ("user_id");

CREATE INDEX ON "cases" ("user_id");

CREATE INDEX ON "cases" ("user_id", "status");

CREATE INDEX ON "cases" ("created_at");

CREATE INDEX ON "case_evidences" ("case_id");

CREATE INDEX ON "case_evidences" ("case_id", "evidence_type");

CREATE INDEX ON "case_status_histories" ("case_id", "created_at");

CREATE INDEX ON "email_drafts" ("case_id");

CREATE INDEX ON "email_drafts" ("case_id", "status");

CREATE UNIQUE INDEX ON "email_draft_attachments" ("email_draft_id", "evidence_id");

CREATE INDEX ON "email_draft_attachments" ("evidence_id");

COMMENT ON TABLE "community_comments" IS '세 게시판의 댓글을 통합 관리한다.
free_post_id, question_post_id, dispute_post_id 중
정확히 하나만 값이 있어야 한다.

is_accept 
';

COMMENT ON TABLE "cases" IS 'case_type:
REFUND_DELAY
REFUND_NOT_PROCESSED
DUPLICATE_CHARGE
PAYMENT_CORRECTION

status:
REGISTERED
ANALYZING
NEED_USER_INFO
WAITING_APPROVAL
IN_PROGRESS
RESOLVED
CLOSED
';

COMMENT ON TABLE "case_evidences" IS 'evidence_type:
ORDER_CONFIRMATION
PAYMENT_RECORD
REFUND_RECORD
SCREENSHOT
PHOTO
CONVERSATION
OTHER

analysis_status:
PENDING
PROCESSING
COMPLETED
FAILED

파일 원본은 백엔드 파일 시스템에 저장한다.
DB에는 파일 경로 및 메타데이터만 저장한다.
';

COMMENT ON TABLE "case_status_histories" IS 'changed_by:
USER
SYSTEM
AI

최초 등록 시 previous_status는 NULL.
사건 상태 변경마다 이력을 기록한다.
';

COMMENT ON TABLE "email_drafts" IS 'purpose:
REFUND_REQUEST
PAYMENT_CORRECTION
ADDITIONAL_INFORMATION
FOLLOW_UP
OTHER

status:
DRAFT
FINALIZED

FINALIZED는 작성 완료 상태이며
Gmail 발송 승인을 의미하지 않는다.

사용자와 AI의 대화에 따라
subject, body를 갱신한다.
';

COMMENT ON TABLE "email_draft_attachments" IS '이메일 초안과 사건 증빙의 N:M 연결 테이블.

하나의 이메일에 여러 증빙 첨부 가능.
하나의 증빙을 여러 이메일에서 재사용 가능.

동일 이메일에 동일 증빙의 중복 첨부 방지.
';

